#include <iostream>

int main() {
    // Multiple stream insertions appending on the same line
    std::cout << "Line" << " 1: ";
    std::cout << "Value\t" << "\"Processed\"\n";

    // Single statement producing multiple lines with an empty line
    std::cout << "Line 2\n\nLine 3 (escaped backslash: \\)\n";

    // Implicit return 0 occurs at the end of main in standard C++
}

#include <iostream>

int main() {
    // Variable declarations with explicit initialization
    int number1 = 0;
    int number2 = 0;
    int sum = 0;

    std::cout << "Enter first integer: ";
    std::cin >> number1;

    std::cout << "Enter second integer: ";
    std::cin >> number2;

    sum = number1 + number2;

    std::cout << "Sum is " << sum << std::endl;
}
